package dev.codex.lastzhelper;
import java.io.*;import java.nio.channels.*;import java.util.*;import org.json.*;
/** Dedicated native-maintenance entry point, separate from truck/bounty workflows. */
public final class MaintenanceController {
 public static void main(String[] args){JSONObject output=new JSONObject();try(DeviceInput.Scope inputs=new DeviceInput.Scope()){
  if(args.length!=7||!(args[0].equals("maintenance-training-start-preview")||args[0].equals("maintenance-base-resource-geometry")||args[0].equals("maintenance-base-bubble-preview")||args[0].equals("maintenance-vip")||args[0].equals("maintenance-alliance-help")||args[0].equals("maintenance-alliance-gifts")||args[0].equals("maintenance-mail-coverage-preview")||args[0].equals("maintenance-mail-preview")||args[0].equals("maintenance-chest-preview")||args[0].equals("maintenance-chest-open-check")||args[0].equals("maintenance-wanted")||args[0].equals("maintenance-wanted-claim-check")||args[0].equals("maintenance-wanted-preview")||args[0].equals("maintenance-training-preview")||args[0].equals("maintenance-training-geometry")||args[0].equals("maintenance-training-collect")))throw new IOException("Choose a supported maintenance workflow");JSONObject options=new JSONObject(args[5]);if(args[0].equals("maintenance-base-resource-geometry")&&!options.optBoolean("dryRun",true))throw new IOException("Resource geometry requires dryRun:true");File dir=new File(args[1]),locks=new File("/data/local/tmp/codex-lastz-helper");locks.mkdirs();
  try(RandomAccessFile file=new RandomAccessFile(new File(locks,"control.lock"),"rw");FileChannel channel=file.getChannel();FileLock lock=channel.tryLock()){
   if(lock==null)throw new IOException("Another controller is active");ControllerOwnership.check();RecoveryGuard.noInjector();try(DisplaySession display=new DisplaySession()){
    AutomationController legacy=new AutomationController(dir,new File(args[2]),new File(args[3]),new File(args[4]),options.optBoolean("dryRun",true),Integer.parseInt(args[6]));legacy.mode=args[0];MaintenanceContext context=new MaintenanceContext(legacy);
    if(options.has("expectedAccountUid")&&!options.getString("expectedAccountUid").equals(context.uid))throw new IOException("Expected maintenance character is not active");
    // Reject an unexpected character before starting the injected inspection session.
    MaintenanceFeature feature=args[0].equals("maintenance-training-start-preview")?new TrainingStartInspectionFeature():args[0].equals("maintenance-base-resource-geometry")?new BaseResourceGeometryFeature():args[0].equals("maintenance-base-bubble-preview")?new BaseBubbleInspectionFeature():args[0].equals("maintenance-vip")?new VipFeature():args[0].equals("maintenance-alliance-help")?new AllianceHelpFeature():args[0].equals("maintenance-alliance-gifts")?new AllianceGiftFeature():args[0].equals("maintenance-mail-coverage-preview")?new MailCoverageInspectionFeature():args[0].equals("maintenance-mail-preview")?new MailInspectionFeature():args[0].equals("maintenance-chest-preview")?new ChestInspectionFeature():args[0].equals("maintenance-chest-open-check")?new ChestOpenInspectionFeature():args[0].equals("maintenance-chest")?new ChestFeature():args[0].equals("maintenance-wanted")?new WantedFeature():args[0].equals("maintenance-wanted-claim-check")?new WantedClaimCheckFeature():args[0].equals("maintenance-wanted-preview")?new WantedInspectionFeature():args[0].equals("maintenance-training-preview")?new TrainingInspectionFeature():args[0].equals("maintenance-training-geometry")?new TrainingGeometryInspectionFeature():new TrainingCollectionFeature();if(feature.requiresInstrumentation()&&!feature.deferInstrumentationUntilAction()&&!context.store.unresolved(context.uid,feature.id()))legacy.input.foreground();List<MaintenanceResult> results=MaintenanceRunner.run(context,Collections.singletonList(feature),false);JSONArray rows=new JSONArray();boolean ok=true;
    for(MaintenanceResult r:results){if(r.outcome==MaintenanceResult.Outcome.FAILED||r.outcome==MaintenanceResult.Outcome.UNCERTAIN)ok=false;rows.put(new JSONObject().put("feature",feature.id()).put("outcome",r.outcome.name()).put("reason",r.reason).put("nextDueMs",r.nextDueMs).put("evidence",new JSONObject(r.evidence)));}
    output.put("event","result").put("ok",ok).put("mode",args[0]).put("accountUid",context.uid).put("maintenance",rows).put("dryRun",context.preview);
   }
  }
 }catch(Throwable e){try{output.put("event","result").put("ok",false).put("stopped",e instanceof InterruptedException).put("error",e.toString());}catch(Exception ignored){}System.out.println(output);System.exit(1);}System.out.println(output);}
}
